// learn from the book of shaders

let mySize;

// a shader variable
let theShader;
let shaderTexture;

let theta = 0;

function preload() {
	theShader = createShader(vert, frag)
}

function setup() {
	frameRate(25);
	 // pixelDensity(1);
	// mySize = max(windowWidth, windowHeight);
	// mySize = 600;
	// shaders require WEBGL mode to work
	createCanvas(windowWidth, windowHeight, WEBGL);
	noStroke();
	shaderTexture = createGraphics(width, height, WEBGL);
	shaderTexture.noStroke();
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

  // shader() sets the active shader with our shader
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", frameCount * 0.001);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/1000.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)/1000.0]);

  // rect gives us some geometry on the screen
  rect(0,0,width, height);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function keyPressed() {
	//noLoop();
	saveCanvas("Shaders_017_2022", "png");
}

// === Tab: frag ===
//noprotect
const frag = `

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;

float random1( in float x) {
	return dot(cos(x), sin(x)) / 0.25;
}

float random2( in vec2 st) {
	return abs(cos(dot(st.xy, vec2(12.9898, 78.233))) * 45758.5453123);
}

float random3(float x, float freq, float t) {
	return step(0.2, random1(floor(x * freq) - floor(t)));
}

void main() {
	float freq = random1(abs(u_time)) + abs(sin(u_time) * 1.1);
	float t = 1.01 + u_time * (1.0 - freq) * .5;
	vec2 st = gl_FragCoord.xy / u_resolution.xy;
	st.x += abs(cos(t + 2.1*st.y * random1(21.0)) * cos(-0.5*st.y * random1(1.0)-t)) * random1(2.0) + random1(0.5);
	st.y -= abs(sin(t/2.0 + 1.1*st.x * random1(1.0)) * cos(0.5*st.x * random1(13.0)-t)) * random1(2.0) + random1(1.0);

	vec3 color = vec3(1.0);
	freq += random1(cos(dot(st.x, st.y)));

	float offset = 2.5 * random1(0.01);
	color = vec3(random3(st.x * 5.0 - offset, st.y * 5.0 + offset, freq * 10.0 - t * offset),
		random3(st.x * 5.0 - offset, st.y * 5.0 + offset, freq * 10.0 + t * offset),
		random3(st.x * 5.0 - offset, st.y * 5.0 + offset, freq * 10.0 + t * offset));

	gl_FragColor = vec4(color, 1.0);
}

`

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

